const html: string = "<div>\n        <p>\n          <h2>1. AVSTRALIYA FUTBOLI</h2>\n        </p>\n        <p>\n          <span>1. Bukmeker garovlarni qabul qiladi:</span>\n        </p>\n        <p>\n          <span>\n            - asosiy vaqt uchun 80 daqiqa (20 daqiqadan to'rtta yarmi yoki ikkita yarmi\n            Har biri 40 daqiqa)\n          </span>\n        </p>\n        <p>\n          <span>\n            - oddiy va qo'shimcha vaqt uchun (\"Shu jumladan.\" belgisi bilan\n            qo'shimcha vaqt\")\n          </span>\n        </p>\n        <p>\n          <span>\n            Noto'g'ri muddat ko'rsatkichlari uchun bukmeyker javobgar emas\n            mos. \"Sport\" va Live bo'limlaridagi ma'lumotlar taxminiydir. Mijozga\n            Rasmiy manbalarga asoslanib, qoidalarni tekshirishingiz kerak.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Esli match by ostanovlen do istecheniya 80 minut, vse stavki\n            1 koeffitsienti bilan hisoblab chiqiladi, bundan mustasno\n            tikish natijalari allaqachon uzilish vaqtida aniq belgilanadi\n            mos.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. O'yin o'tkaziladigan joy o'zgargan taqdirda, tikilgan garovlar\n            mezbon jamoa o'zgarishsiz qolishi sharti bilan kuchda qoladi\n            jamoa.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Birinchi gol uradi” garovi. Agar o'yinchi o'yinda ishtirok etmagan bo'lsa yoki\n            Birinchi gol urilgandan keyin maydonga kirdi, barcha garovlar yoqilgan\n            u haqiqiy emas deb hisoblanadi. O'yinchilarga tikish\n            birinchi gol kiritilgunga qadar almashtirilgan yoki maydondan chetlatilgan;\n            yo'qotish. Agar birinchi gol bo'lmagan o'yinchi tomonidan kiritilsa\n            koeffitsientlar taklif qilindi, keyin barcha garovlar boshqa o'yinchilarga edi\n            tanlov berilmasa, yo'qotish\n            \"Boshqa o'yinchi\" garovi. Agar o'yin avval tark etilgan bo'lsa\n            birinchi gol uriladi, barcha garovlar bekor qilinadi.\n          </span>\n        </p>\n        <p>\n          <strong>2. AMERIKA FUTBOLI</strong>\n        </p>\n        <p>\n          <span>1. Bukmeker garovlarni qabul qiladi:</span>\n        </p>\n        <p>\n          <span>\n            - asosiy vaqt uchun (60 daqiqa o'yin vaqti to'rtga bo'lingan\n            chorak 15 daqiqa)\n          </span>\n        </p>\n        <p>\n          <span>\n            - oddiy va qo'shimcha vaqt uchun (\"Shu jumladan.\" belgisi bilan\n            qo'shimcha vaqt\")\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, barcha garovlar hisob-kitob qilinadi\n            1 koeffitsient bilan, natijasi aniq bo'lgan garovlar bundan mustasno\n            o'yin to'xtatilgunga qadar belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Garovlar haqiqiy deb hisoblanishi uchun o'yin davom etmasligi kerak\n            55 daqiqadan kam. Bu holda, barcha tikishlar asosida hisoblanadi\n            o'yin to'xtatilgan paytdagi natijalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Agar jamoa saralashdan o'ta olmasa, \"Turnir oxirida yuqoriroq\" garovlari uchun\n            guruhdan malaka, garovlar ularning pozitsiyasiga qarab hisoblanadi\n            guruhda. Agar jamoalar bir xil o'rinlarni egallasa, tikish\n            hisob-faktura asosida hisoblab chiqiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. “Eng samarali chorak” garovi. Agar imkonsiz bo'lsa\n            eng samarali chorakni aniq belgilang (masalan, ikkita\n            yoki chorakdan ko'prog'i bir xil hisob bilan yakunlangan), shunga o'xshash garovlar\n            choraklar 1 koeffitsient bilan hisob-kitob qilinadi. Qolganlariga tikish\n            chorak yo'qotadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Eng samarali yarim” garovi. Agar ikkala yarmi bilan yakunlangan bo'lsa\n            bir xil ball bilan garovlar 1 koeffitsient bilan hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Agar o‘yin, qo‘shimcha taymlarni ham qo‘shib hisoblaganda, durang natija bilan yakunlansa,\n            bir yoki boshqa jamoaning g'alabasiga garovlar hisob-kitob qilinadi\n            koeffitsient 1 (garov summalari qaytariladi). Jami va nogironlar\n            o'yin natijalariga ko'ra hisoblab chiqiladi.\n          </span>\n        </p>\n        <p>\n          <strong>3. BADMINTON, STOL TENNISI, PAYLASH VOLEYBOLI</strong>\n        </p>\n        <p>\n          <span>\n            1. Agar o'yinning boshlanishi kechiktirilsa yoki qoldirilsa, barcha garovlar\n            o'yin yoki turnir oxirigacha yoki oxirigacha amal qiladi\n            ishtirokchilardan birining ishtiroki.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar o'yin birovning rad etilishi yoki diskvalifikatsiyasi tufayli to'xtatilgan bo'lsa\n            jamoalardan, barcha garovlar 1 koeffitsient bilan hisoblanadi, bundan tashqari\n            natijasi o'yinning to'xtatilgan vaqti bilan aniq belgilanadi. B\n            Bunday holda, o'yin g'olibiga garovlar hisob-kitob qilinadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Sportchilarning bosh harflaridagi xatolar tufayli (masalan, B. Smit o‘rniga\n            A. Smit) garovlari bekor qilinmaydi. Bunday holda, stavkalar saqlanib qoladi\n            amal qiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “O'yin g'olibi” garovi. Agar o'yinchi garovda ko'rsatilgan bo'lsa\n            o'yin boshlanishidan oldin almashtirilgan bo'lsa, barcha garovlar bekor hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Badminton, stol tennisi, plyaj tennisi bo'yicha nogironlik va to'plamlar\n            voleybol balllarda ko'rsatilishi kerak, bundan mustasno “Gandikap tomonidan\n            to'plamlar\" va \"Jami to'plamlar\".\n          </span>\n        </p>\n        <p>\n          <span>\n            6. \"G'olib\" garovi. Birinchi o'rinni egallagan sportchi (jamoa).\n            turnir g'olib deb hisoblanadi. Agar sportchi ishtirok etishdan bosh tortsa\n            Turnir boshlanishidan oldin unga garovlar hisob-kitob qilinadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <strong>4. BASKETBOL</strong>\n        </p>\n        <p>\n          <span>1. Bukmeker garovlarni qabul qiladi:</span>\n        </p>\n        <p>\n          <span>\n            - asosiy vaqt uchun (48 daqiqa o'yin vaqti, 4 chorak 12\n            daqiqa yoki 40 daqiqa o'yin vaqti, 4 chorak 10 daqiqa), NCAA da\n            (Milliy kollej atletika assotsiatsiyasi) - 20 tadan ikkita yarmi\n            daqiqa\n          </span>\n        </p>\n        <p>\n          <span>\n            - oddiy va qo'shimcha vaqt uchun (\"Shu jumladan.\" belgisi bilan\n            qo'shimcha vaqt\")\n          </span>\n        </p>\n        <p>\n          <span>\n            Statistik garovlar qo'shimcha vaqtni o'z ichiga oladi,\n            agar boshqacha ko'rsatilmagan bo'lsa. Boshqa tikish shartlari ko'rsatilishi mumkin\n            tikish bo'limi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, o'yinga garovlar\n            1 koeffitsienti bilan hisoblab chiqiladi, natijasi allaqachon bo'lganlar bundan mustasno\n            o'yin to'xtatilgan vaqtga qarab belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin 40 daqiqa davom etsa, garovlar hisobga olinadi\n            amal qiladi, o'yin kamida 35 daqiqa davom etishi kerak. Qachon\n            Gamblinglar hisobga olinishi uchun o'yin davomiyligi 48 daqiqa\n            amal qiladi, o'yin kamida 40 daqiqa davom etishi kerak. Bunday holda\n            Barcha hollarda, barcha garovlar o'sha paytdagi natijalar asosida hisoblanadi\n            o'yinni to'xtatish.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. NBA jamoalarini ketma-ket ro'yxatga olish mumkin\n            (mezbonlar - mehmonlar) va aksincha. Teskari tartibga solish holatida\n            Gamblinglar uchun pul qaytarilmaydi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Basketbol bo'yicha o'rtoqlik (kubok, klub) o'yinlari reglamenti\n            mijoz tomonidan rasmiy manbalardan mustaqil ravishda aniqlashtiriladi. Agar\n            O'rtoqlik uchrashuvi durang bilan yakunlandi (o'yin reglamenti o'zgartirildi), keyin\n            g'olibga tikilgan garovlar 1 koeffitsient bilan hisoblanadi. Jami va\n            nogironlar olingan natijaga ko'ra hisoblab chiqiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Basketbol kubogi bahslarida qo'shimcha vaqt beriladi\n            ikkita o'yin natijalarining yig'indisiga asoslanib, faqat garovlarda hisobga olinadi\n            keyingi bosqichga, boshqa ligaga, musobaqa g'olibiga va\n            va hokazo.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Basketbol o'yini durang bilan yakunlansa, \"Will\" garovi.\n            qo'shimcha vaqt\" g'alaba qozonadi, va \"Bo'lmaydi\n            qo'shimcha vaqt\" yutqazadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. “Sport” bo‘limidagi “Birinchi bo‘lim/to‘liq o‘yin vaqti” garovida\n            \"P\" g'alabani, \"X\" esa durangni anglatadi. Natija birinchi bo'lib ro'yxatga olinadi\n            o'yinning birinchi yarmi, keyin esa asosiy vaqt natijasi. Masalan,\n            W1W2 birinchi bo'limda birinchi jamoa (W1) g'alaba qozonishini anglatadi\n            O'yinda ikkinchi jamoa (W2) asosiy vaqtda g'alaba qozonadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Eng samarali chorak” garovi. Agar eng samarali bo'lsa\n            chorakni aniq belgilash mumkin emas (ikki yoki undan ko'p bo'lsa\n            chorak bir xil natija bilan yakunlandi), bularga tikish\n            choraklar 1 koeffitsienti bilan hisob-kitob qilinadi. Boshqa choraklarga garovlar\n            mag'lub bo'lish (4-chorakning yakuniy ochkolari aniqlanganda, ochkolar,\n            qo'shimcha vaqtda qo'yilgan ochkolar hisobga olinmaydi).\n          </span>\n        </p>\n        <p>\n          <span>\n            10. “Eng samarali yarim” garovi. Agar ikkala yarmi bilan yakunlangan bo'lsa\n            bir xil natija, garovlar 1 (dyuym) koeffitsienti bilan hisob-kitob qilinadi\n            ikkinchi bo'lim natijasida qo'shimcha vaqtda to'plangan ochkolar hisoblanmaydi\n            hisobga olinadi).\n          </span>\n        </p>\n        <p>\n          <span>\n            11. “Jamoa... ikkala bo‘limda ham g‘alaba qozonadi” garovi. Ikkinchisi natijasida\n            yarmi, qo'shimcha vaqtda to'plangan ochkolar hisobga olinmaydi.\n            \"Jamoa ... ikkala yarmida ham g'alaba qozonmaydi\" garovi g'alaba qozonadi\n            belgilangan jamoa kamida yarmini tenglashtiradi yoki yo'qotadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            12. “Ikkala jamoa 72,5 balldan ko‘p to‘playdi” garovi. Gambling g'alaba qozonadi\n            agar o'yin davomida ikkala jamoa 73 yoki undan ko'p ball to'plagan bo'lsa.\n          </span>\n        </p>\n        <p>\n          <span>\n            13. “Ikkala jamoa 72,5 balldan ko'p to'plamaydi” garovi. Baho\n            agar kamida bitta jamoa ko'rsatilgan natijaga erisha olmasa g'alaba qozonadi\n            natija.\n          </span>\n        </p>\n        <p>\n          <span>\n            14. “Har chorakning jami 32,5 balldan ortiq” garovi. Baho\n            har birida to'plangan ballarning umumiy soni bo'lsa g'alaba qozonadi\n            chorak - 33 yoki undan ko'p.\n          </span>\n        </p>\n        <p>\n          <span>\n            15. “Choraklar bo'yicha handikap” garovi. Masalan, “2 Handikap by\n            chorak -2,5”. Yakuniy hisob 81:102 (17:22, 26:25, 18:20, 20:35),\n            ya'ni choraklardagi hisob 1:3 (mos ravishda 0:1, 1:0, 0:1, 0:1).\n            Gambling yutqazdi, chunki 2-jamoaga handikap qo'llanilgan\n            chorak hisob 1:0,5 bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            16. \"6-10 ball farqi bilan g'alaba qozoning\" garovi g'alaba qozonadi\n            birinchi va ikkinchi jamoaning ochkolari o'rtasidagi ochkolar farqi bo'ladi\n            6 dan 10 ballgacha. Misol: o'yin hisobi (85:90), farq\n            2-jamoaning g'alabalari soni 5 ta, shuning uchun garov yutqazadi.\n          </span>\n        </p>\n        <p>\n          <strong>5. BEYSBOL, SOFTBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Beysbol o'yinlariga garovlar asosiy vaqtda qabul qilinadi, agar\n            boshqacha aytilmagan.\n          </span>\n        </p>\n        <p>\n          <span>\n            Gamblinglarni qabul qilishda boshlang'ich ko'zalarning nomlari hisobga olinadi,\n            agar ma'lum bir sport tadbirida ismlar ko'rsatilgan bo'lsa. Ikkalasi ham\n            ko'zalar maydonga kirishlari va kamida bitta pitch qilishlari kerak,\n            garovlar haqiqiy deb hisoblanishi uchun. Agar biron sababga ko'ra\n            sanab o'tilgan ko'zalardan hech biri maydonga tushmagan, barcha garovlar hisobga olinadi\n            yaroqsiz. Agar boshlang'ich ko'zalar ro'yxatda bo'lmasa, tikish\n            boshlang'ich ko'zalar kim bo'lishidan qat'iy nazar qabul qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Uchrashuvda mezbon jamoa ikkinchi o'rinni egallagan jamoadir,\n            o'yin joyidan qat'i nazar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Barcha garovlar rasmiy o'yin natijalariga ko'ra hisob-kitob qilinadi\n            shu jumladan qo'shimcha inninglar (qismlarga qo'yilgan garovlar bundan mustasno).\n            mos).\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Agar kamida beshta garov o'ynalsa, barcha garovlar haqiqiy hisoblanadi\n            full innings or 4.5 innings. If less than 4.5 innings are played, then\n            quyidagilar hisoblab chiqiladi: g'alabaga garovlar; passage to the next stage; stavkalari,\n            natijalari o'sha paytda aniq belgilangan edi\n            o'yinni to'xtatish. All other bets on this match are settled with\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. O'yindan oldingi garovlar. Agar beysbol o'yini belgilangan vaqtda boshlanmasa\n            vaqt va rasmiy veb-saytida o'yinning qoldirilishi haqida tasdiq bor, keyin\n            Ushbu o'yindagi barcha garovlar 1 koeffitsient bilan hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. O'yin davomida qilingan garovlar. Agar o'yin to'xtatilsa (to'xtatilgan) va\n            72 soat ichida tiklanadi, keyin tikishlar o'z kuchini saqlab qoladi\n            o'yin oxiri. Agar o'yin 72 soat ichida yakunlanmasa, unda hamma narsa\n            unga tikilgan garovlar bekor bo'ladi, allaqachon mavjud tanlovlar bundan mustasno\n            belgilangan edi.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Softbol - bu to'p bilan jamoaviy o'yin, beysbolning o'ynaladigan versiyasi\n            kichikroq maydonda katta to'p bilan o'ynash. Rasmiy jamoaviy o'yinlarda\n            etti inning o'ynang. Agar ball teng bo'lsa, qo'shimcha\n            innings.\n          </span>\n        </p>\n        <p>\n          <strong>6. BIATHLON</strong>\n        </p>\n        <p>\n          <span>\n            1. “Yuqorroq joy egallaydi” garovi. Ikkisidan qaysi birini tanlash\n            biatlonchilar (yoki jamoalar) finalda yuqori o'rinni egallaydi\n            reyting. Agar ikkala nomzod ham poygadan chiqsa yoki ulardan biri\n            ular boshlay olmaydi, garovlar 1 koeffitsient bilan hisoblanadi.\n            Agar nomzodlardan birortasi marraga yeta olmasa, barcha garovlar yoqilgan\n            ular mag'lubiyatga uchragan deb hisoblanadilar.\n          </span>\n        </p>\n        <p>\n          <strong>7. BOKS, JANGI SPORT</strong>\n        </p>\n        <p>\n          <span>\n            1. Jangning boshlanishi birinchi raund oldidan gong ovozi bilan ko'rsatiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar jang haqiqiy emas deb topilsa yoki biron bir sababga ko'ra to'xtatilgan bo'lsa\n            g'olib aniqlanmaguncha, barcha garovlar hisobga olinadi\n            yaroqsiz. Agar jang natijasi allaqachon aniqlangan bo'lsa, tikish\n            e’lon qilingan natijalar asosida hisoblab chiqiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar raundlar soni o'zgartirilgan bo'lsa, jang natijasiga tikish\n            amal qiladi, lekin turlar soniga tikish\n            1 koeffitsienti bilan hisoblab chiqiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Raundlar soni” garovi. Turlar sonini bashorat qilish\n            Jang Tikishni hisoblash uchun faqat yakunlangan raundlar hisobga olinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Agar sportchi raund boshida gongdan keyin ringga chiqmasa, jang\n            oldingi turda yakunlangan deb hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <strong>8. Velosiped poygasi</strong>\n        </p>\n        <p>\n          <span>\n            1. Birinchi saralash poygasining boshlanishi turnirning boshlanishi hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Duelga garovlar (sportchilar yoki jamoalar). Hisoblash uchun tikish uchun\n            amal qiladi, ikkala raqib ham rasmiy chiziqni kesib o'tishi kerak\n            boshlash.\n          </span>\n        </p>\n        <p>\n          <span>\n            - Raqiblardan biri biron sababga ko'ra musobaqani tark etsa\n            raqobat, uning raqibi g'olib deb e'lon qilinadi\n          </span>\n        </p>\n        <p>\n          <span>\n            - Agar raqiblardan biri yoki ikkalasi ham rasmiy chiziqni kesib o'ta olmasa\n            start, garovlar 1 koeffitsient bilan hisoblanadi\n          </span>\n        </p>\n        <p>\n          <span>\n            - Agar ikkala ishtirokchi ham musobaqadan chiqib ketsa, g'olib chavandoz hisoblanadi\n            eng ko'p aylanishlarni yakunladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            - Agar ikkala haydovchi ham bir davrada o'tkazib yuborilsa, garovlar bo'yicha hisob-kitob qilinadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. “Yuqorroq joy egallaydi” garovi. Ikki poygachidan qaysi birini tanlash\n            (yoki jamoalar) yakuniy reytingda yuqori o'rinni egallaydi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Finalda bir vaqtning o'zida bir nechta chavandozlar bo'lsa\n            reytingda, reytingda yuqoriroq bo'lgan kishi g'olib hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <strong>9. SUV POLOSI</strong>\n        </p>\n        <p>\n          <span>\n            1. Barcha garovlar asosiy vaqtdagi natijalarga qarab hisoblanadi\n            (32 daqiqa o'yin vaqti, 8 daqiqadan to'rt chorak).\n          </span>\n        </p>\n        <p>\n          <span>\n            Noto'g'ri muddat ko'rsatkichlari uchun bukmekerlik kompaniyasi javobgar emas\n            o'yinlar. \"Sport\" va Jonli bo'limlarda ko'rsatilgan ma'lumotlar ko'rsatkichdir.\n            Mijoz suv polosi qoidalarini amaldor bilan tekshirishi kerak\n            manbalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Faqat qo'shimcha vaqt va penaltilar seriyasi hisobga olinadi\n            malaka, g'alaba va shunga o'xshash natijalarga tikish.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, barcha garovlar hisob-kitob qilinadi\n            1 koeffitsient bilan, natijasi bo'lgan garovlar bundan mustasno\n            o'yin to'xtatilgunga qadar aniq belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Garovlar haqiqiy deb hisoblanishi uchun o'yin davom etmasligi kerak\n            30 daqiqadan kam. Bu holda, barcha tikishlar asosida hisoblanadi\n            o'yin to'xtatilgan paytdagi natijalar.\n          </span>\n        </p>\n        <p>\n          <strong>10. VOLEYBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, o'yinga garovlar\n            1 koeffitsienti bilan hisoblab chiqiladi, natijasi allaqachon bo'lganlar bundan mustasno\n            o'yin to'xtatilgan vaqt bilan aniq belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar to'plam oxirigacha o'ynalmasa, allaqachon aniq bo'lgan natijalar\n            uzilish vaqtida aniqlanadi, garovlarni hisoblashda hisobga olinadi.\n            Boshqa barcha garovlar 1 koeffitsient bilan hisoblanadi. Agar to'siq bo'lsa\n            oxirigacha o'ynadi, lekin o'yin yakunlanmadi, ushbu setga tikilgan garovlar hisobga olinadi\n            amal qiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Voleybolda nogironlik va totallar ballarda ko'rsatiladi, bundan mustasno\n            \"Setlar bo'yicha handikap\" va \"To'plamlar\" ga garovlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “To'plamlar bo'yicha hisob” garovi. \"Sport\" bo'limida tegishli ustunlar\n            huquqiga ega 3:0, 3:1 va boshqalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. “3 (5, va hokazo) ball uchun poyga” garovi. Bu jamoani tanlash\n            to'plam uchun belgilangan ball sonini birinchi bo'lib oladi. Agar jamoa\n            har qanday sababga ko'ra undan oldin o'ynashni davom ettirishdan bosh tortsa yoki\n            uning raqibi belgilangan miqdordagi ochko to'plagan bo'lsa, garovlar hisob-kitob qilinadi\n            1 koeffitsienti bilan.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Tay-brek” garovi. Natija - beshinchi to'plam bo'ladimi. Baho\n            Beshinchi set sodir bo'lsa, \"taybreyk bo'ladi\" g'alaba qozonadi.\n          </span>\n        </p>\n        <p>\n          <strong>11. GANDBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Gamblinglar asosiy yakundagi natijaga qarab hisoblanadi\n            vaqt (60 daqiqa o'yin vaqti, 30 daqiqalik ikki davr).\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Qo'shimcha vaqt va penaltilar seriyasi faqat qachon hisobga olinadi\n            quyidagi garovlarni hisoblash: “Keyingi bosqichga chiqish”, “Boshqasiga chiqish\n            liga», «G'alaba» va shunga o'xshashlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. O'yin davomida qo'yilgan garovlar. Agar o'yin yakunlanmagan bo'lsa, hammasi\n            garovlar 1 koeffitsient bilan hisob-kitob qilinadi, bu natijalar bundan mustasno\n            o'yin uzilishidan oldin aniq belgilab qo'yilgan edi.\n          </span>\n        </p>\n        <p>\n          <strong>12. GOLF</strong>\n        </p>\n        <p>\n          <span>\n            1. Asosiy golf turnirlari uch yoki to'rt kun davom etadi. General\n            Teshiklar soni odatda 72 ni tashkil qiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. O'yin ishtirokchisi deb hisoblanish uchun o'yinchi birinchi bo'lishi kerak\n            zarba. Agar golfchi o'ynashni davom ettirishdan bosh tortsa, barcha garovlar unga bo'ladi\n            yo'qotish.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. “Turnirda g'alaba qozon” garovi. Birinchi o'rinni egallagan golfchi\n            turnir g'olib deb hisoblanadi. G'olib tomonidan aniqlanadi\n            pley-off natijalari, agar bunday bosqich qoidalarda nazarda tutilgan bo'lsa\n            turnir.\n          </span>\n        </p>\n        <p>\n          <strong>13. DART</strong>\n        </p>\n        <p>\n          <span>\n            1. Match tikish. Agar o'yin boshlangan bo'lsa, lekin tugallanmagan bo'lsa, o'yinchi\n            keyingi bosqichga o'tgan g'olib hisoblanadi. Biroq, tariflar\n            muayyan to'plam, oyoq va nogironlik, shuningdek, maxsus tikish uchun\n            agar bu garovning natijasi aniqlanmagan bo'lsa, bekor bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Darts o'yinlaridagi handikaplar va to'plamlar to'plamlarda ko'rsatilgan, agar\n            \"Sport\" bo'limida boshqa hech narsa ko'rsatilmagan. Maksimal mumkin\n            bir yondashuvda uchta otish natijasi 180 ga teng.\n          </span>\n        </p>\n        <p>\n          <strong>14. KURILMA</strong>\n        </p>\n        <p>\n          <span>\n            1. Körling o'yinlariga garovlar qo'shimcha uchlarini o'z ichiga oladi, agar\n            boshqacha aytilmagan. O'yin 10 ta yakundan iborat. Agar o'ndan keyin tugaydi\n            durang, qo'shimcha end o'ynaladi. Qo'shimcha yakunda g'olib\n            o'yin g'olibi deb e'lon qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Uyda bitta tosh yoki ikkita tosh bo'lmasa\n            uyning markaziga eng yaqin bo'lgan raqiblar bir xilda\n            uyning markazidan masofa, yakuniy hisob 0:0 bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, o'yinga garovlar\n            1 koeffitsienti bilan hisoblab chiqiladi, natijasi allaqachon bo'lganlar bundan mustasno\n            o'yin to'xtatilgan vaqtga qarab belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Barcha garovlar kamida beshta to'liq bo'lsa, haqiqiy hisoblanadi\n            endov. Bunday holda, barcha garovlar natijaga qarab hisoblanadi\n            o'shanda o'yin to'xtatilgan edi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Jamoa hamma narsani qo'yib yubormasa, hisobdan qat'iy nazar mag'lub bo'ladi\n            toshlaringizni o'z vaqtida (bir uchida jamoalar navbatma-navbat\n            sakkizta toshni qo'yib yuboring).\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Barcha garovlar rasmiy natijalar asosida hisob-kitob qilinadi,\n            shu jumladan qo'shimcha uchlari (qismlarga qo'yilgan garovlar bundan mustasno).\n            mos).\n          </span>\n        </p>\n        <p>\n          <strong>15. KRIKET</strong>\n        </p>\n        <p>\n          <span>\n            1. Gamblinglar rasmiy natijalar asosida hisob-kitob qilinadi,\n            ushbu o'yin yoki turnir tashkilotchilari tomonidan e'lon qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar o'yin to'xtatilgan va yakunlanmagan bo'lsa, unga tikish\n            natijalar bundan mustasno, 1 koeffitsienti bilan hisoblanadi\n            uchrashuvning to'xtatilgan vaqti bilan aniq belgilandi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin g'olibi D/L usuli bo'yicha aniqlansa, garovlar\n            natijalari \"1x2\" va &quot;O'yin g'olibi&quot; hisoblab chiqiladi\n            D/L usuli natijalariga ko'ra. Boshqa natijalar bo'yicha hisoblab chiqiladi\n            haqiqiy o'yin natijasi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Eng yaxshi zarba beruvchi” garovi. Eng ko'p ball to'plagan o'yinchi g'alaba qozonadi\n            har bir o'yinda yugurishlar soni.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. “Eng yaxshi bouler” garovi. Eng ko'p ball to'plagan o'yinchi g'alaba qozonadi\n            har bir o'yindagi darvozalar soni. Agar bu ko'rsatkich teng bo'lsa\n            keyingi mezon ECON - eng ko'p bo'lgan o'yinchi\n            wickets va eng kam ECON yutadi. Agar o'yinchilar bir xil bo'lsa\n            Qabul qilingan darvozalar soni va ECON, eng yaxshi bouller tomonidan aniqlanadi\n            number of missed runs.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Individual Total Rns” garovi birinchi X oversga. Holatda\n            D/L usulida garov bajarilgan overslar bo'yicha hisoblanadi\n            o'yin tugashidan oldin.\n          </span>\n        </p>\n        <p>\n          <strong>16. PAYLASH FUTBOLI</strong>\n        </p>\n        <p>\n          <span>\n            1. Barcha garovlar asosiy yakundagi natijaga qarab hisoblanadi\n            vaqt (36 daqiqa o'yin vaqti, har biri 12 daqiqadan uchta davr).\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Noto'g'ri ma'lumotlar uchun bukmekerlik kompaniyasi javobgar emas\n            o'yin davomiyligi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Jonli yoki \"Sport\" bo'limlarida ko'rsatilgan ma'lumotlar taxminiydir.\n            Mijoz qoidalarni rasmiy manbalarda tekshirishi kerak.\n          </span>\n        </p>\n        <p>\n          <strong>17. RUGBY</strong>\n        </p>\n        <p>\n          <span>\n            1. Barcha garovlar asosiy yakundagi natijaga qarab hisoblanadi\n            vaqt (80 daqiqa o'yin vaqti, 40 daqiqadan ikki bo'lim).\n          </span>\n        </p>\n        <p>\n          <span>\n            Noto'g'ri muddat ko'rsatkichlari uchun bukmeyker javobgar emas\n            mos. Jonli yoki \"Sport\" bo'limlarida ko'rsatilgan ma'lumotlar\n            indikativ. Mijoz amaldorda qoidalarni tekshirishi kerak\n            manbalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Qo'shimcha vaqt va penaltilar seriyasi faqat qachon hisobga olinadi\n            \"Keyingi bosqichga o'tish\" va \"Turnirda g'alaba qozonish\" garovlarini hisoblash.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Gamblinglar haqiqiy bo'lishi uchun o'yin o'tkazilishi kerak.\n            to'liq, natijasi aniq bo'lgan garovlar bundan mustasno\n            o'yin to'xtatilgunga qadar belgilanadi.\n          </span>\n        </p>\n        <p>\n          <strong>18. Qovoq</strong>\n        </p>\n        <p>\n          <span>\n            1. Agar o'yin boshlangan bo'lsa, lekin biron bir sababga ko'ra yakunlanmagan bo'lsa\n            (masalan, o'yinchini rad etish yoki diskvalifikatsiya qilish) buning natijasi\n            o'yin to'xtatilganda allaqachon aniq aniqlangan (masalan,\n            birinchi o'yin natijasi, birinchi o'yinning jami va boshqalar), hisobga olinadi\n            stavkalarni hisoblashda. Boshqa barcha garovlar dan hisoblanadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Sport tadbiri tashkilotchilarining qaroriga ko'ra, o'yinlar soni\n            uchdan beshgacha bo'lishi mumkin va o'yin davom etishi mumkin\n            uchta o'yinda jamoalardan birining g'alabasi.\n          </span>\n        </p>\n        <p>\n          <strong>19. SNUKER</strong>\n        </p>\n        <p>\n          <span>\n            1. Match tikish. Agar o'yin to'xtatilsa, o'yinchi o'tib ketadi\n            hech bo'lmaganda keyingi bosqich g'olib hisoblanadi\n            bitta ramka.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Frame tikish, handikap, maxsus tikish. Gambling uchun\n            haqiqiy deb hisoblangan, barcha ramkalar to'ldirilishi kerak,\n            o'yin g'olibini aniqlash uchun zarur. Agar g'olib bo'lsa\n            har qanday sababga ko'ra o'yin tugashidan oldin aniqlangan bo'lsa, barcha garovlar yoqilgan\n            ramkalar va nogironlar, shuningdek, maxsus garovlar bilan hisob-kitob qilinadi\n            1 koeffitsienti, natijasi allaqachon bo'lgan garovlar bundan mustasno\n            aniq belgilangan.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yinchi istalgan kadrda mag'lubiyatga uchrasa,\n            Ushbu freymdagi handikaplar va totallar bo'yicha garovlar hisob-kitob qilinadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. “Birinchi cho'ntagiga tushgan to'p ko'k”ga tikish. Agar tikish g'alaba qozonadi\n            Qoidalarga ko'ra cho'ntagiga solingan birinchi rangli to'p ko'k (to'p ranglari:\n            sariq, yashil, jigarrang, ko'k, pushti, qora).\n          </span>\n        </p>\n        <p>\n          <strong>20. TENNIS</strong>\n        </p>\n        <p>\n          <span>\n            1. Agar o'yinchi ishtirok etishdan bosh tortsa (yoki diskvalifikatsiya qilingan bo'lsa).\n            o'yin boshlanishi, garovlar qaytariladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar o'yin boshlanishi kechiktirilsa yoki biron sababga ko'ra o'yin qoldirilgan bo'lsa\n            sababi, barcha garovlar o'yin yoki turnir oxirigacha amal qiladi,\n            doirasida o'yin o'tkazilmoqda.\n          </span>\n        </p>\n        <p>\n          <span>3. Quyidagi hollarda garovlar o'z kuchini saqlab qoladi:</span>\n        </p>\n        <p>\n          <span>- sudlarning sirtini o'zgartirish</span>\n        </p>\n        <p>\n          <span>- joyni o'zgartirish</span>\n        </p>\n        <p>\n          <span>- yopiq sudni ochiq sudga almashtirish</span>\n        </p>\n        <p>\n          <span>\n            4. Agar tennis musobaqasi rad etish yoki diskvalifikatsiya tufayli to'xtatilgan bo'lsa\n            o'yinchi, o'yin boshlanishidan oldin qo'yilgan barcha garovlar qaytarilishi mumkin\n            (1 koeffitsient bilan hisoblangan). Jonli tikish ham bekor bo'ladi\n            (1 koeffitsient bilan hisoblangan), bundan mustasno\n            natijalarning natijalari o'yin to'xtatilgan vaqtda allaqachon aniqlangan edi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Tennis o'yini uchun nogironlik va total o'yinlarda ko'rsatilgan.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Agar biron sababga ko'ra o'yin tugallanmagan bo'lsa (masalan, o'yin\n            uzilib qolgan va tugallanmagan, o'yinchi o'ynashni davom ettirishdan bosh tortadi yoki\n            diskvalifikatsiya qilingan va h.k.), ushbu o'yinga garovlar hisob-kitob qilinadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. Tennis bahslarida g'alaba qozonish uchun hal qiluvchi setda\n            siz 10 ball yutib olishingiz kerak, handikap va jami ochkolar bo'yicha hisoblanadi va\n            Butun o'yin hal qiluvchi set 1 o'yin sifatida hisoblanadi. Masalan, mos\n            Grönefeld/Peshke – Nikulesku/Zakopalova. Jami 21,5 dan kam pul tikish.\n            Hisob 6:3, 3:6, 4:10 ball. Uchinchi set bitta o'yin hisoblanadi. Jami\n            6 + 3 + 3 + 6 + 1 = 19 bo'ladi. Gambling g'alaba qozondi.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. Tennis o'yinlarida \"chempion tay-brek\" yoki \"super\"\n            dan taybreaker handikap va butun o'yin uchun jami hisoblanadi\n            super taybreykdagi hisobni hisobga olgan holda.\n          </span>\n        </p>\n        <p>\n          <span>\n            Masalan, Grönefeld/Peshke – Nikulesku/Zakopalova (chempion.\n            taybrek). Jami 21,5 dan kam pul tikish. Uchrashuv hisobi 6:3; 3:6; 4:10\n            ball. Jami 6 + 3 + 3 + 6 + 4 + 10 = 32 bo'ladi. Gambling yutqazildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            Super taybreyk (chempionlik taybreyk) ba'zi turnirlarda o'ynaladi\n            hal qiluvchi to'plam o'rniga. O'yinchi o'yin g'olibi deb hisoblanadi\n            (juftlik), birinchi bo'lib 2 ball to'plash sharti bilan 10 ball oladi\n            raqibingizdan ko'proq ochko.\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “To'plamlar bo'yicha hisob” garovi. \"Sport\" bo'limidagi mos garovlar\n            huquqiga ega 2:0, 2:1 va boshqalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            10. \"G'olib\" garovi. G'olib tennischi (jamoa),\n            turnirida birinchi o‘rinni egalladi. Agar tennischi o'ynashdan bosh tortsa\n            Turnir boshlanishidan oldin, unga garovlar hisob-kitob qilinadi\n            koeffitsient 1.\n          </span>\n        </p>\n        <p>\n          <span>\n            11. \"O'yinda g'alaba qozoning\" garovi. Tennischini g'alaba qozonish uchun tanlash\n            belgilangan o'yin. O'yinlarning uzluksiz raqamlanishi faqat o'yinlarda amal qiladi\n            to'plam ichida. \"8-o'yin 2-set\"ga tikish, ikkinchi setda hisob bilan\n            Sakkizinchi o'yin bo'lmagani uchun 6:1 hisobi 1 koeffitsient bilan hal qilinadi\n            edi.\n          </span>\n        </p>\n        <p>\n          <span>12. Tay-breyk bitta alohida o'yin sifatida hisoblanadi.</span>\n        </p>\n        <p>\n          <span>\n            “1/2 boshqa hisob bilan yutadi” garovi ulardan birining g'alabasini nazarda tutadi\n            6:6 hisobdan keyin tay-brekda (yoki super taybrekda).\n            hisob 9:9).\n          </span>\n        </p>\n        <p>\n          <span>Misol: Klein - Kleck. “1 boshqa hisob bilan yutadi” garovi:</span>\n        </p>\n        <p>\n          <span>- Tay-brek 7:3 hisobida yakunlandi - garov yutqazildi</span>\n        </p>\n        <p>\n          <span>\n            - Tay-brek 8:6 hisobida yakunlandi - garov g'alaba qozondi, chunki\n            Hisob 6:6 bo'lganidan keyin 1-futbolchi g'alaba qozondi.\n          </span>\n        </p>\n        <p>\n          <strong>21. FLOORBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Floorbol - bandy o'yinining bir turi\n            yopiq joylarda, teshiklari bo'lgan plastik to'p bilan qattiq maydonda.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Barcha garovlar asosiy yakundagi natijaga qarab hisoblanadi\n            vaqt (60 daqiqa o'yin vaqti, har biri 20 daqiqadan uchta davr).\n          </span>\n        </p>\n        <p>\n          <span>\n            Noto'g'ri muddat ko'rsatkichlari uchun bukmekerlik kompaniyasi javobgar emas\n            mos. \"Sport\" va Jonli bo'limlarda ko'rsatilgan ma'lumotlar ko'rsatkichdir.\n            Mijoz qoidalarni rasmiy manbalarda tekshirishi kerak.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Qo'shimcha vaqt va penaltilar seriyasi faqat qachon hisobga olinadi\n            quyidagi garovlarni hisoblash: \"Keyingi bosqichga o'tish\", \"G'alaba qozonish\n            turniri” va shunga o'xshash.\n          </span>\n        </p>\n        <p>\n          <strong>22. FUTBOL</strong>\n        </p>\n        <p>\n          <span>\n            1. Futbol o'yinlariga (shu jumladan kubok o'yinlariga) garovlar qabul qilinadi\n            Reglamentda belgilangan o'yinning asosiy vaqti (90 daqiqa o'yin, 2 ta bo'lim).\n            45 daqiqa plyus o'yinning jarohat vaqti), agar bo'limda bo'lsa\n            “Sport” boshqacha ko‘rsatmaydi (“qo‘shimcha vaqt”).\n          </span>\n        </p>\n        <p>\n          <span>\n            Qo'shimcha vaqt va penaltilar seriyasi faqat garovlar uchun hisobga olinadi\n            “Keyingi bosqichga o‘tish”, “Boshqa ligaga chiqish”, “Turnirda g‘alaba qozonish”\n            va shunga o'xshash.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Barcha garovlar haqiqiy bo'lishi uchun 80 o'ynash kerak\n            o'yin daqiqalari, tikish natijalari allaqachon mavjud bo'lgan hollar bundan mustasno\n            o'yin to'xtatilgan vaqtda aniq belgilangan.\n          </span>\n        </p>\n        <p>\n          <span>3. O'rtoqlik o'yinlari formati.</span>\n        </p>\n        <p>\n          <span>\n            Yoshlar o‘rtasidagi o‘rtoqlik o‘yinlarining davomiyligi bo‘yicha FIFA reglamenti:\n          </span>\n        </p>\n        <p>\n          <span>\n            - U18, U17, U16, U15 jamoalari uchun - 80 daqiqa (har biri 40 daqiqadan ikki taym)\n          </span>\n        </p>\n        <p>\n          <span>\n            - U14 jamoalari uchun - garovlar uchun 70 daqiqa (har biri 35 daqiqadan ikki taym).\n            haqiqiy edi, o'yinning 70 daqiqasi o'ynalgan bo'lishi kerak\n          </span>\n        </p>\n        <p>\n          <span>\n            - U13 va U12 jamoalari uchun - 60 daqiqa (har biri 30 daqiqadan ikki taym)\n            garovlar haqiqiy edi, o'yinning 60 daqiqasi o'ynalishi kerak\n          </span>\n        </p>\n        <p>\n          <span>\n            O'rtoqlik o'yinlari uchun reglament turnir boshlanishidan oldin qabul qilinadi.\n            O'rtoqlik o'yinlariga pul tikishdan oldin o'yin qoidalarini aniqlab olishingiz kerak\n            mustaqil axborot manbalarida.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Jahon kubogi va chempionat uchun “Turnir yakunida yuqoriroq” garovlari\n            UEFA Yevropa qaysi bosqichgacha bo'lganiga qarab hisoblab chiqiladi\n            jamoalar yetib kelishdi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Eng ko'p gol urgan jamoaga garovlar yoki - ichida\n            Jahon chempionati va UEFA Evropa chempionati haqida - har bir jamoa uchun,\n            kim eng ko'p (eng kam) gol urgan (o'tkazib yuborgan),\n            qo'shimcha vaqtni hisobga olgan holda hisoblab chiqiladi, lekin bundan mustasno\n            o'yindan keyingi penaltilar. Agar jamoalar gol (yoki o'tkazib yuborish) teng bo'lsa\n            gollar soni, garovlar 1 koeffitsient bilan hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Qo'shimcha vaqt” deb belgilangan futbol o'yinlariga garovlar kiritilmaydi\n            o'yindan keyingi penaltilar hisobga olinadi. O'yindan keyingi penaltilarga pul tikish\n            alohida qabul qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. “Jamoa birinchi burchakni oladi” garovi. Qaysi ekanligini aniqlash kerak\n            burchak to'pini birinchi bo'lib jamoa egallaydi.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. “Jamoa ko'proq burchak to'pini oladi” garovi. Qaysi ekanligini aniqlash kerak\n            o'yin davomida ko'proq burchak to'pini amalga oshiradi.\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Ust/past burchaklar soni”ga tikish. Aniqlash kerak\n            taklif qilingan qiymatdan ko'p yoki kamroq burchaklar beriladi\n            har ikki jamoaning o'yin jarayoni.\n          </span>\n        </p>\n        <p>\n          <span>\n            10. Sariq kartochkalarga garovlar. Jami sariq kartochkalar va sariq handikap\n            kartalar - faqat maydon o'yinchilariga ogohlantirishlar va\n            darvozabon. Uchrashuvdagi sariq kartochkalar sonini sanashda takrorlang\n            pleyerni avtomatik ravishda olib tashlashga olib keladigan ogohlantirish\n            maydonlar hisobga olinmaydi. Sariq va qizil kartochkalar maydonga ko'rsatiladi\n            O'yinchilar va darvozabonning so'nggi hushtagidan keyin qachon e'tiborga olinmaydi\n            stavkalarni hisoblash.\n          </span>\n        </p>\n        <p>\n          <span>\n            11. Sariq va qizil kartochkalarga garovlar (qisqartirilgan nomi JK/K\n            yoki \"kartalar\") quyidagicha hisoblanadi: sariq kartochka - 1\n            kartochka, qizil kartochka 2 sariq kartochka. Sariqni takrorlang\n            karta e'tiborga olinmaydi va bitta qizil kartochka hisoblanadi. Ya'ni\n            bitta o'yinchida jami 3 tadan ko'p bo'lmagan kartalar bo'lishi mumkin.\n          </span>\n        </p>\n        <p>\n          <span>\n            12. Sariq va qizil kartochkalar, burchaklar, zarbalar soni\n            Shtanga va shtanga video translyatsiya orqali aniqlanadi. Agar\n            eshittirish amalga oshirilmadi yoki to'xtatildi, keyin sariq/qizil soni\n            kartochkalar va burchaklar rasmiy ma'lumot manbalaridan olingan.\n            Rasmiy manbaga ko'ra, 46-daqiqada o'zgarish amalga oshirildi.\n            hisob-kitob qilish uchun tanaffus vaqtida tugallangan hisoblanadi. Burchak kim\n            qayta topshirilgan, hisoblash maqsadida u bitta deb hisoblanadi. Umumiy hisobda\n            Burchaklar uchun faqat olingan burchaklar hisobga olinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            13. O'yindan keyingi penaltilarga garovlar. Agar o'yindan keyingi penaltilarda\n            beshinchi penalti bajarilmadi, quyidagi garovlar qaytariladi:\n          </span>\n        </p>\n        <p>\n          <span>- “2-jamoa beshinchi penaltini tepmaydi”</span>\n        </p>\n        <p>\n          <span>- “2-jamoa beshinchi penaltini tepadi”</span>\n        </p>\n        <p>\n          <span>\n            14. Gambling “O‘yinchi birinchi golni uradi va jamoa hisobda g‘alaba qozonadi”.\n            Siz birinchi golni urgan o'yinchini va oxiridagi hisobni taxmin qilishingiz kerak\n            o'yinning asosiy vaqti (shu jumladan jarohat vaqti). Agar\n            futbolchi o'yinda qatnashmagan yoki bo'lganidan keyin maydonga kirmagan\n            birinchi gol kiritilsa, garov 1 koeffitsient bilan hisob-kitob qilinadi. Agar\n            birinchi gol avtogol (avtogol), keyin garov o'yinchiga,\n            Bu golni kim urgan bo'lsa, 1 koeffitsient bilan hal qilinadi. Agar o'yin bo'lsa\n            birinchi gol urilganidan keyin to'xtatildi va yakunlanmadi\n            qoidalarda ko'rsatilgan shartlar, keyin bu golni kiritgan o'yinchiga tikish\n            maqsad 1 koeffitsient bilan hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>1-misol:</span>\n        </p>\n        <p>\n          <span>\n            1-garov “Adam Lallana birinchi golni uradi va 1-jamoa g'alaba qozonadi\n            hisob 1-0”\n          </span>\n        </p>\n        <p>\n          <span>\n            2-garov “Deyan Lovren birinchi golni uradi va 1-jamoa g'alaba qozonadi\n            hisob 1-0”\n          </span>\n        </p>\n        <p>\n          <span>Vaziyat 1:</span>\n        </p>\n        <p>\n          <span>\n            Adam Lallana birinchi golni urdi va 1-jamoa 1:0 hisobida g'alaba qozondi:\n          </span>\n        </p>\n        <p>\n          <span>- garov 1 yutdi</span>\n        </p>\n        <p>\n          <span>- tikish 2 yutqazdi</span>\n        </p>\n        <p>\n          <span>2-misol:</span>\n        </p>\n        <p>\n          <span>\n            Adam Lallana maydonga tushmadi va 1-jamoa 1:0 hisobida g'alaba qozondi:\n          </span>\n        </p>\n        <p>\n          <span>- 1 garov qaytariladi</span>\n        </p>\n        <p>\n          <span>- tikish 2 yutqazdi</span>\n        </p>\n        <p>\n          <span>\n            15. Kartochkalar. Statistika. Gamblinglar voqealar asosida amalga oshiriladi\n            o'yinning asosiy vaqtida sodir bo'ladi. Faqat kartalar hisobga olinadi\n            maydonda o'yinchilarga ko'rsatildi.\n          </span>\n        </p>\n        <p>\n          <span>\n            \"Birinchi karta\" garovi. Gamblinglar voqealar asosida hisoblanadi\n            o'yinda belgilangan vaqt oralig'ida sodir bo'lgan. Qizil\n            yoki sariq kartochkalar belgilangan muddatda ko'rsatilishi kerak\n            o'yin vaqti. Agar voqea sodir bo'lsa, karta hisobga olinmaydi\n            ma'lum bir vaqtda sodir bo'lgan ogohlantirish (yoki olib tashlash) natijasida\n            vaqt, lekin karta ma'lum keyin ko'rsatilgan\n            vaqt davri.\n          </span>\n        </p>\n        <p>\n          <span>\n            \"Jami kartalar\" garovi. Gambling uchun, qo'shimcha\n            (kompensatsiyalangan) vaqt. Qo'shimcha vaqt hisobga olinmaydi\n            boshqacha ko'rsatilgan hollar bundan mustasno. Faqat bitta karta bo'ladi\n            ikkinchi qoidabuzarlik uchun hisoblanadi. Ya'ni, agar sariq kartochka ortida bo'lsa\n            darhol qizil kartochka, keyin faqat bitta hisoblanadi\n            karta. Shunga ko'ra, kartalarning maksimal soni\n            bir o'yinchi olishi mumkin bo'lgan ikkiga teng.\n          </span>\n        </p>\n        <p>\n          <span>\n            “Oxirgi karta” garovi. Agar o'yinda hech kim ko'rsatilmagan bo'lsa\n            kartalar, keyin yutuq natijasi \"Kartalar yo'q\". Boshqa barcha garovlar\n            yo'qotish. Ikki yoki undan ortiq o'yinchi bir xil vaziyatda ishtirok etsa,\n            tikish oxirgi ko'rsatilgan karta asosida hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            16. Gambling \"1-jamoa 78:00 daqiqagacha 1-raqamli gol uradi -\n            Ha&quot; — 1-jamoa o'zining birinchi golini urishini aniqlashingiz kerak\n            bu vaqt oralig'ida. Agar gol 78-daqiqada kiritilsa\n            daqiqa, bu garovni hisoblashda hisobga olinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            17. “Penalti va chetlatish (ha)” garovi. Gambling hisoblab chiqiladi\n            Agar o'yin penalti va o'chirishni o'z ichiga olsa, g'alaba qozonadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            18. “O‘yinchi gol uradi...” garovi. Gambling hisoblab chiqiladi\n            agar o'yinchi maydonga kirsa va gol ursa g'alaba qozonadi. O'z darvozasi\n            hisobga olingan.\n          </span>\n        </p>\n        <p>\n          <span>\n            - garov o'yindan oldin qilingan - agar o'yinchi maydonga tushmagan bo'lsa, u holda\n            stavka daromad bilan hisoblanadi. Narxlar faqat uchun amal qiladi\n            asosiy tarkibning o'yinchilari, ya'ni o'yinchi o'rinbosar sifatida kelgan bo'lsa va\n            garovlar o'yindan oldin berilgan bo'lsa, bunday kuponlar hisoblab chiqiladi\n            qaytish\n          </span>\n        </p>\n        <p>\n          <span>\n            - garov jonli ravishda amalga oshirildi - agar o'yinchi maydonga kirsa, u holda\n            garovlar uning gollari soniga qarab hisoblanadi\n          </span>\n        </p>\n        <p>\n          <strong>23. FUTSAL</strong>\n        </p>\n        <p>\n          <span>\n            1. Barcha garovlar asosiy yakundagi natijaga qarab hisoblanadi\n            vaqt (40 daqiqa o'yin vaqti, har biri 20 daqiqadan ikkita davr).\n          </span>\n        </p>\n        <p>\n          <span>\n            Noto'g'ri muddat ko'rsatkichlari uchun bukmekerlik kompaniyasi javobgar emas\n            mos. \"Sport\" va Jonli bo'limlarda ko'rsatilgan ma'lumotlar ko'rsatkichdir.\n            Mijoz qoidalarni rasmiy manbalarda tekshirishi kerak.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Qo'shimcha vaqt va 6 metrlik nuqtadan penaltilar seriyasi\n            faqat quyidagi garovlarda hisobga olinadi: keyingi bosqichga chiqish,\n            turnirda g'alaba qozonish va shunga o'xshash.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, barcha garovlar hisob-kitob qilinadi\n            1 koeffitsient bilan, natijasi aniq bo'lgan garovlar bundan mustasno\n            o'yin to'xtatilgunga qadar belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Uchrashuvni rasman yakunlangan deb hisoblash uchun o'yin davom etishi kerak\n            kamida 35 daqiqa. Bu holda, barcha tikishlar asosida hisoblanadi\n            o'yin to'xtatilgan paytdagi natijadan.\n          </span>\n        </p>\n        <p>\n          <strong>24. CHAMONDA XOKKEY</strong>\n        </p>\n        <p>\n          <span>\n            1. Barcha garovlar asosiy yakundagi natijaga qarab hisoblanadi\n            vaqt (70 daqiqa o'yin vaqti, 35 daqiqalik ikki davr yoki\n            17 daqiqa 30 soniyadan iborat to'rtta davr).\n          </span>\n        </p>\n        <p>\n          <span>\n            Noto'g'ri muddat ko'rsatkichlari uchun bukmekerlik kompaniyasi javobgar emas\n            mos. \"Sport\" va Jonli bo'limlarda ko'rsatilgan ma'lumotlar ko'rsatkichdir.\n            Mijoz qoidalarni rasmiy manbalarda tekshirishi kerak.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Qo'shimcha vaqt va penaltilar seriyasi faqat hisobga olinadi\n            quyidagi garovlar: keyingi bosqichga chiqish, turnirda g'alaba qozonish va\n            o'xshash.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, barcha garovlar hisob-kitob qilinadi\n            1 koeffitsient bilan, natijasi aniq bo'lgan garovlar bundan mustasno\n            o'yin to'xtatilgunga qadar belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Uchrashuvni rasman yakunlangan deb hisoblash uchun o'yin davom etishi kerak\n            kamida 60 daqiqa. Bu holda, barcha tikishlar asosida hisoblanadi\n            o'yin to'xtatilgan paytdagi natijadan.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Yopiq xokkey - yopiq xokkeyning bir turi\n            binolar. Uchrashuv 20 daqiqadan iborat ikki taymdan iborat.\n          </span>\n        </p>\n        <p>\n          <strong>25. MUZLI XOKKEY</strong>\n        </p>\n        <p>\n          <span>\n            1. “Sport” bo‘limidagi garovlar asosiy vaqt uchun qabul qilinadi (60 daqiqa\n            o'yinlar, 20 daqiqadan iborat 3 ta davr), agar boshqacha ko'rsatilmagan bo'lsa (bunda\n            qo'shimcha vaqtni hisobga olgan holda \"OT dan\" belgilangan\n            vaqt va otishmalar \"OT va otishmalar bilan\" belgilangan).\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Live bo'limidagi garovlar faqat asosiy vaqt uchun qabul qilinadi, agar\n            eslatmalar o'yinning boshqa segmentini ko'rsatmaydi. Jonli tikish\n            \"Qo'shimcha vaqt\" deb belgilangan o'yinlar faqat qo'shimcha vaqt hisoblanadi va o'z ichiga olmaydi\n            otishma seriyasi.\n          </span>\n        </p>\n        <p>\n          <span>KHL va NHL o'yinlariga jonli garovlar qabul qilinadi:</span>\n        </p>\n        <p>\n          <span>- oddiy vaqt uchun</span>\n        </p>\n        <p>\n          <span>\n            - qo'shimcha vaqtni hisobga olgan holda asosiy vaqt uchun (\"dan\n            OT”)\n          </span>\n        </p>\n        <p>\n          <span>\n            - asosiy vaqt uchun, qo'shimcha vaqt va otishmalarni hisobga olgan holda (bilan\n            \"OT va otishmalar bilan\" belgilangan)\n          </span>\n        </p>\n        <p>\n          <span>\n            1-misol: Buffalo Sabers - Toronto Maple Leafs (qo'shimcha\n            vaqt va otishmalar). Bunday holda, o'yinga garovlar qabul qilinadi\n            asosiy vaqt, shu jumladan qo'shimcha vaqt va otishmalar. Hisob\n            o‘yin 2:3 (1:0, 1:1, 0:1, 0:0, 0:1). Barcha garovlar hisob-kitob qilinadi\n            yakuniy hisob 2:3 asosida. Ushbu o'yin uchun umumiy gollar bo'ladi\n            5.\n          </span>\n        </p>\n        <p>\n          <span>\n            Misol 2. Buffalo Sabres - Toronto Maple Leafs (OT bilan). Bu holda\n            o'yinga garovlar hisobga olingan holda asosiy vaqt uchun qabul qilinadi\n            qo'shimcha vaqt. O'yin uchun yakuniy hisob ko'rib chiqiladi\n            hisob 2:2 (1:0, 1:1, 0:1; 0:0). Ushbu o'yin uchun umumiy gollar bo'ladi\n            4. 1 va 2-jamoalarning g'alabasiga tikilgan garovlar mag'lub bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            Misol 3. Buffalo Sabres - Toronto Maple Leafs. Bu holda tariflar\n            faqat oddiy soatlar uchun qabul qilinadi. Ushbu o'yin uchun yakuniy hisob\n            hisob 2:2 (1:0, 1:1, 0:1) hisoblanadi. Ushbu o'yindagi umumiy gollar\n            4 ga teng bo'ladi. 1 va 2-jamoalarning g'alabasiga garovlar yutqaziladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar o'yin boshlangan bo'lsa, lekin yakunlanmagan bo'lsa, barcha garovlar hisob-kitob qilinadi\n            1 koeffitsient bilan, natijasi aniq bo'lgan garovlar bundan mustasno\n            o'yin to'xtatilgunga qadar belgilanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Garovlar haqiqiy deb hisoblanishi uchun o'yin davom etmasligi kerak\n            55 daqiqadan kam. Bu holda, barcha tikishlar asosida hisoblanadi\n            o'yin to'xtatilgan paytdagi natija.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. NHL, AHL, CHL, OHL, WHL, Sharqiy Xokkey Ligasi jamoalari\n            Shimoliy Amerika qirg'oqlari to'g'ri chiziqda joylashgan bo'lishi mumkin\n            ketma-ketlik (mezbonlar - mehmonlar), va aksincha. Holatda\n            Teskari buyurtmalar bo'yicha to'lovlar qaytarilmaydi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. “Total” garovi. Chiziqdagi shaybalar soni, shu jumladan otishmalar\n            umumiy hisobda g'olib jamoaning otishmalarda urgan gollari\n            tomonidan kiritilgan gollar soni esa 1 ta gol sifatida qabul qilinadi\n            mag'lubiyatga uchragan jamoaning zarbasi 0 deb hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. “Gol 1 va 7 daqiqalar oralig'ida” garovi. Agar gol 7 da kiritilsa\n            daqiqa 00 soniya, u 8-daqiqada kiritilgan hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. Quyidagi garovlar qayd etilgan natijaga qarab hisob-kitob qilinadi yoki\n            sport tadbiri rasmiy tashkilotchilarining reytingi:\n            \"Turnir yakunida yuqoriroq\", \"Chempionat g'olibi\", \"G'olib\n            guruh”, “Olingan ochkolar”, “Urilgan gollar” va “o‘tkazib yuborilgan gollar”.\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Natija va jami past/yuqori”ga tikish. Aniqlash kerak\n            o'yinda qaysi jamoa g'alaba qozonadi va nechta gol uriladi (ko'proq\n            yoki belgilangan miqdordan kamroq). NHL va KHL o'yinlariga tikish va\n            shuningdek, boshqa chempionatlar va xalqaro musobaqalar o'yinlari uchun\n            muntazam soatlar uchun qabul qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            10. “3 (5, va hokazo) ball uchun poyga” garovi. Aniqlash kerak\n            qaysi jamoa o'yinda belgilangan miqdordagi ochkoni birinchi bo'lib oladi.\n            Agar jamoa biron sababga ko'ra o'yinni davom ettirishdan bosh tortsa\n            u yoki raqibi belgilangan miqdordagi ballni qanday to'plaganligi,\n            garovlar 1 koeffitsient bilan hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            11. “2-jamoa qo'shimcha vaqtda g'alaba qozonadi - Yo'q” garovi. Baho\n            o'yinda yoki 2-jamoada qo'shimcha vaqt bo'lmasa, g'alaba qozonadi\n            qo'shimcha vaqtda mag'lub bo'ldi. Otishma g'alabasiga garovlar\n            xuddi shunday hisoblab chiqiladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            12. “Qo'shimcha vaqtda g'alaba qozoning” garovi. G'olib bo'lishi kerak\n            qo'shimcha vaqtda (OT) qaror qabul qiladi.\n          </span>\n        </p>\n        <p>\n          <span>O'yin hisobi (0:0; 1:1; 1:0) – mag'lubiyat.</span>\n        </p>\n        <p>\n          <span>O'yin hisobi (0:0; 1:1; 0:0; 0:1) – g'alaba.</span>\n        </p>\n        <p>\n          <span>O‘yin hisobi (0:0; 1:1; 0:0; 0:0; 1:0) – mag‘lubiyat.</span>\n        </p>\n        <p>\n          <strong>26. BOWLES</strong>\n        </p>\n        <p>\n          <span>\n            1. Garovlar setlar va o'yinlar bo'yicha qabul qilinadi. Barcha to'plamlar o'ynalishi kerak\n            o'yinda. Agar biron sababga ko'ra g'olib oldindan aniqlangan bo'lsa\n            o'yin oxirida, setlarga garovlar bekor qilinadi, bundan mustasno\n            keyingi o'yin natijaga ta'sir qiladigan holatlar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar g'olib barcha setlar tugagunga qadar aniqlansa, garov tikiladi\n            o'yin g'olibi rasmiy natijaga ko'ra hisoblanadi, bilan\n            kamida bitta uchi oxirigacha o'ynalgan bo'lsa.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Agar barcha kiritilgan o'yinchilar o'yin boshlanishidan oldin almashtirilsa, barcha garovlar\n            haqiqiy emas deb hisoblanadi.\n          </span>\n        </p>\n        <p>\n          <strong>27. FORMULA 1, MOTOSIKL POYGASI, SPEEDWAY</strong>\n        </p>\n        <p>\n          <span>\n            1. Agar poyga yakunlanmagan bo'lsa va rasmiy natijalar bo'lmasa\n            e'lon qilingan, garovlardan tashqari barcha garovlar bekor\n            natijasi allaqachon aniq belgilangan.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Gamblinglar Xalqaro reyting asosida hisoblanadi\n            Avtomobil assotsiatsiyasi (FIA) mavsumning so'nggi poygasidan so'ng darhol.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. “Head to Head” garovi. Ikkalasidan qaysi biri ekanligini aniqlash kerak\n            ko'rsatilgan chavandozlar yaxshiroq ishlaydi. Bilan tugatgan chavandoz\n            poygadagi eng yaxshi o'rin (yakuniy reytingda) bajarilgan deb hisoblanadi\n            yaxshiroq.\n          </span>\n        </p>\n        <p>\n          <span>\n            Garov tikish uchun ikkala drayver ham ishga tushishi kerak\n            poyga. Agar ikkala chavandoz ham marraga erisha olmasa, tikish\n            tugallangan davrlar asosida hisoblab chiqiladi. Ikkala chavandoz ham tashqarida bo'lsa\n            poygadan tashqarida, eng ko'p aylana bosib o'tgan haydovchi hisoblanadi\n            yaxshiroq ishladi. Agar ikkala chavandoz ham poygadan durang holda chiqsa\n            yakunlangan davrlar soni, garovlar koeffitsient bilan hisoblanadi\n            1. Agar haydovchi tez aylanishni bajara olmasa (to'g'ri kelmasa\n            saralash vaqti), uning o'rni yakuniy start bilan belgilanadi\n            pozitsiyalar.\n          </span>\n        </p>\n        <p>\n          <strong>28. Counter-Strike: GO</strong>\n        </p>\n        <p>\n          <span>\n            1. Tariflar rasmiy e'lon qilinganlar asosida hisoblanadi\n            natijalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar bo'lajak o'yinlar ro'yxatida noaniqliklar bo'lsa, biz zaxiraga olamiz\n            garovlarni bekor qilish huquqini o'zida saqlab qoladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Texnik g'alaba yoki o'yindan voz kechilgan taqdirda, hammasi beqaror\n            tikish bekor.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Agar o'yin yoki xarita tugallanmagan bo'lsa, barcha tikilgan garovlar\n            bekor qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Agar uzilish tufayli o'yin yoki xarita takrorlansa yoki\n            o'yinchi bilan bog'liq bo'lmagan texnik muammolar, barchasi\n            Hisob-kitob qilinmagan garovlar bekor bo'ladi. Xaritani yoki oʻyinni takrorlash uchun\n            Alohida tariflar beriladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Agar kartalarning standart soni o'zgarsa yoki undan farq qilsa\n            tikish qo'yish uchun belgilangan, biz huquqni saqlab\n            tikishlarni bekor qilish.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Taklif etilgan barcha bozorlar, agar qo'shimcha ish haqi bilan hisob-kitob qilinadi\n            boshqacha aytilmagan.\n          </span>\n        </p>\n        <p>\n          <strong>29. Dota 2</strong>\n        </p>\n        <p>\n          <span>\n            1. Tariflar rasmiy e'lon qilinganlar asosida hisoblanadi\n            natijalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar bo'lajak o'yinlar ro'yxatida noaniqliklar bo'lsa, biz zaxiraga olamiz\n            garovlarni bekor qilish huquqini o'zida saqlab qoladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Texnik g'alaba yoki o'yindan voz kechilgan taqdirda, hammasi beqaror\n            tikish bekor.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Agar o'yin yoki xarita tugallanmagan bo'lsa, barcha tikilgan garovlar\n            bekor qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Agar o'yin yoki xarita uzilganligi sababli takrorlansa yoki\n            o'yinchi bilan bog'liq bo'lmagan texnik muammolar, barchasi\n            Hisob-kitob qilinmagan garovlar bekor bo'ladi. Xaritani yoki oʻyinni takrorlash uchun\n            Alohida tariflar beriladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Agar kartalarning standart soni o'zgarsa yoki undan farq qilsa\n            tikish qo'yish uchun belgilangan, biz huquqni saqlab\n            tikishlarni bekor qilish.\n          </span>\n        </p>\n        <p>\n          <span>\n            7. “Map – first aegis” garovi asosida hisoblanadi\n            kim Aegisni olib, Roshanni o'ldirmaydi.\n          </span>\n        </p>\n        <p>\n          <span>\n            8. “Xarita – birinchi minora” garovi. Minorani yo'q qilishning har qanday usuli\n            hisoblar (minorani o'rmalash bilan vayron qilish, minora vayron qilish\n            raqibingiz yoki o'yinchingiz minorani rad eting).\n          </span>\n        </p>\n        <p>\n          <span>\n            9. “Xarita – birinchi kazarma” garovi. Barakni yo'q qilishning har qanday usuli\n            hisoblar (qo'rg'onni sudralib ketish, kazarmani yo'q qilish).\n            raqib yoki o'yinchingiz tomonidan barakni rad etish).\n          </span>\n        </p>\n        <p>\n          <strong>30. AFSONLAR LIGASI</strong>\n        </p>\n        <p>\n          <span>\n            1. Tariflar rasmiy e'lon qilinganlar asosida hisoblanadi\n            natijalar.\n          </span>\n        </p>\n        <p>\n          <span>\n            2. Agar bo'lajak o'yinlar ro'yxatida noaniqliklar bo'lsa, biz zaxiraga olamiz\n            garovlarni bekor qilish huquqini o'zida saqlab qoladi. Texnik g'alaba yoki\n            Agar siz o'ynashdan bosh tortsangiz, barcha hal qilinmagan garovlar bekor bo'ladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            3. Texnik g'alaba yoki o'yindan voz kechilgan taqdirda, hammasi beqaror\n            tikish bekor.\n          </span>\n        </p>\n        <p>\n          <span>\n            4. Agar o'yin yoki xarita tugallanmagan bo'lsa, barcha tikilgan garovlar\n            bekor qilinadi.\n          </span>\n        </p>\n        <p>\n          <span>\n            5. Agar o'yin yoki xarita uzilganligi sababli takrorlansa yoki\n            o'yinchi bilan bog'liq bo'lmagan texnik muammolar, barchasi\n            Hisob-kitob qilinmagan garovlar bekor bo'ladi. Xaritani yoki oʻyinni takrorlash uchun\n            Alohida tariflar beriladi.\n          </span>\n        </p>\n        <p>\n          <span>\n            6. Agar kartalarning standart soni o'zgarsa yoki undan farq qilsa\n            tikish qo'yish uchun belgilangan, biz huquqni saqlab\n            tikishlarni bekor qilish.\n          </span>\n        </p>\n      </div>\n";
